% interface to terminal command linefunction fBridge(funcName, hasInput, hasOutput)  page_screen_output(false);   % prevent paging artifacts  %% -------- read JSON input ONLY if needed --------  if hasInput    myJson = '';    while true      myStr = fgets(stdin);      if myStr == -1        break;      else        myJson = [myJson, myStr];      endif    endwhile    myData = jsondecode(myJson);    funcArgs = myData.args;    % must be a cell array  endif  %% -------- execution --------  % ---- preset output structure (single creation) ----  outStruct           = struct();  outStruct.ok        = false;  outStruct.log       = "";  outStruct.result    = [];  outStruct.error     = struct("message","", "id","", "stack",[]);  try    if hasOutput      if hasInput        [logStr, result] = evalc("feval(funcName, funcArgs{:});");      else        [logStr, result] = evalc("feval(funcName);");      endif      outStruct.result = result;    else      % ---- NO JSON output → fast execution ----      if hasInput        [logStr, ~] = evalc("feval(funcName, funcArgs{:});");      else        [logStr, ~] = evalc("feval(funcName);");      endif    endif    % ---- success mutation ----    outStruct.ok     = true;    outStruct.log    = logStr;  catch err    % ---- failure mutation ----    outStruct.ok = false;    outStruct.error.message  = err.message;    outStruct.error.id       = err.identifier;    outStruct.error.stack    = err.stack;  end_try_catch  printf("%s", jsonencode(outStruct));endfunction